using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.Congruence.QuadraticOrderMoments;
internal sealed class CalderonReciprocalMomentsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Calderon's reciprocal moments satisfy both congruences for every admissible imaginary quadratic order.",
        H("Calderon's Reciprocal Moment Congruences"),
        Blocks(
            Definition("r", "R", "The local quadratic order", Params(Eqn(Ring, Call("AdjoinRoot", Polynomial))),
                "The source writes Oomega,p := Zp[omega] (page 19). The ring is AdjoinRoot of X squared minus T X plus N over the p-adic integers. X is the polynomial indeterminate and C embeds a coefficient; the displayed integer casts are into PadicInt p."),
            Definition("element", "element", "Coordinates in the chosen basis",
                Params(All("x", Nat, All("y", Nat, Eqn(Element(V("x"),V("y")),
                    Add(Coerce(V("x"),Ring), Mul(Coerce(V("y"),Ring), Root)))))),
                "Equation (6.1), page 18, is omega squared minus T omega plus N equals zero, with T,N integers and negative discriminant. The distinguished root is AdjoinRoot.root of this polynomial. The source's expression x+yomega uses the displayed natural coordinates and ring casts."),
            Definition("admissible", "Admissible", "The imaginary and inert hypotheses",
                Params(Iffn(Adm, And(Less(Num(5),P), And(Less(Disc,Num(0)), And(
                    new Formula.Not(Parenthesized(Dvd(Coerce(P,Int),Disc))),
                    Eqn(Call("legendreSym",P,Disc),new Formula.Negate(Num(1)))))))),
                "Equations (6.1) and (6.3) require T,N in Z, Delta=T squared minus 4N < 0, p>5, p not dividing Delta, and its Legendre symbol equal to -1. The bracket assumption supplies the prime instance."),
            Definition("u", "U", "The literal set of positive representatives",
                Params(All("k",Nat,Eqn(Representatives, LiteralSet()))),
                "Source expression (page 19): For k ≥ 1, define Uω,k := {x+yω : 1 ≤ x,y ≤ pᵏ, p ∤ (x,y)}. U is a finite set of ring elements, obtained as the image of the positive coordinate rectangle after excluding simultaneous divisibility. The existential coordinate binders express precisely that image; p^k is included in each coordinate."),
            Definition("h1", "H1", "The reciprocal first moment",
                Params(All("k",Nat,Eqn(Call("H1",P,T,N,K),SumOver(Call("RingInverse",Z))))),
                "Source expression (page 19): Hr,ω(k) := ∑z∈Uω,k z⁻ʳ. Here r=1 and the sum is over the ring elements of U. RingInverse is Mathlib Ring.inverse: for a unit z it is val((hz.unit)^(-1)), where hz proves IsUnit z. It is zero on nonunits. Every representative in the admissible setting is a unit, so that extension adds no terms or hypotheses to the source sum."),
            Definition("h2", "H2", "The reciprocal second moment",
                Params(All("k",Nat,Eqn(Call("H2",P,T,N,K),SumOver(Pow(Call("RingInverse",Z),Num(2)))))),
                "The same source formula Hr,ω(k) := ∑z∈Uω,k z⁻ʳ (page 19), with r=2, squares the underlying inverse unit value. The finite set and inverse convention are exactly those of H1."),
            Describe.Lean(DescribeId.Create("calderon-reciprocal-moment-claim"), Handle("claim"),
                H("Conjecture 6.3"), StatementSource.FromAuthor(Disp(Iffn(V("claim"),ClaimFormula()))),
                AssessedProvenance.FromRepo(Note),
                Blocks(Paragraph(Text("Conjecture 6.3 (page 19): Let ω satisfy (6.1), and let p satisfy (6.3). Then, for every k ≥ 1,")),
                    new DocumentBlock.DisplayFormula(Params(Imp(Adm,All("k",Nat,Imp(Leq(Num(1),K),MomentBounds()))))),
                    Paragraph(Text("The source's displayed conclusion is H₁,ω(k) ∈ p²ᵏ𝒪ω,p, H₂,ω(k) ∈ pᵏ𝒪ω,p. The explicit hp binder supplies the prime instance in the calls to Admissible, R, H1 and H2. IdealSpan of a singleton is the principal ideal generated by that ring power. The source states a conjecture.")),
                    Paragraph(Text("<table><thead><tr><th>Public definition</th><th>Source expression (pages 18–19)</th><th>Encoding</th></tr></thead><tbody><tr><td>R</td><td>𝒪ω,p := ℤp[ω]</td><td>AdjoinRoot of X²−TX+N over PadicInt p</td></tr><tr><td>element</td><td>x+yω</td><td>Natural casts and AdjoinRoot.root</td></tr><tr><td>Admissible</td><td>Equations (6.1), (6.3)</td><td>Negative discriminant; p&gt;5; nondivisibility; Legendre symbol −1</td></tr><tr><td>U</td><td>{x+yω : 1≤x,y≤pᵏ, p∤(x,y)}</td><td>Finite image of the filtered positive rectangle in R</td></tr><tr><td>H1</td><td>Hr,ω(k) := ∑z∈Uω,k z⁻ʳ, r=1</td><td>Sum over U of Ring.inverse, the underlying inverse unit value</td></tr><tr><td>H2</td><td>Hr,ω(k) := ∑z∈Uω,k z⁻ʳ, r=2</td><td>Sum over U of the squared inverse unit value</td></tr></tbody></table>"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("calderon-reciprocal-moment-result"),Handle("result"),
                H("The moment conjecture holds"), StatementSource.FromAuthor(Disp(V("claim"))),
                AssessedProvenance.FromRepo(Note),
                Blocks(Paragraph(Text("Positive coordinates identify U bijectively with the units of the finite quadratic quotient. Multiplication by 2 permutes those units; cancellation of 3 makes their inverse-square sum zero. Reflect each coordinate a<p^k to p^k-a and fix a=p^k. The resulting affine correction has two boundary strips; each reduces to a scalar inverse-square sum modulo p^k. The exact inverse identity then gives the first-moment bound after cancellation of 2. Both conjuncts hold for every admissible parameter, without an extra assumption.")),
                    Paragraph(Text("For a positive representative and any unit u with that underlying value, the identity below specifies the value without naming a proof term.")),
                    new DocumentBlock.DisplayFormula(Params(All("x",Nat,All("y",Nat,All("u",Call("Units",Ring),
                        Imp(Eqn(Coerce(V("u"),Ring),Element(V("x"),V("y"))),
                            Eqn(Call("val",V("u")),Element(V("x"),V("y"))))))))),
                    Paragraph(Text("The omega-Ljunggren and omega-Bailey conjectures remain separate conclusions; their reciprocal-moment premise is discharged. Sharpness remains open."))), DescribeRole.Theorem,
                new OpenProblemResolutionClaim(
                    ProblemSlugRef.Create("calderon-2026-quadratic-order-reciprocal-moments"),
                    ResolutionKind.Proved)))));
    private static DocumentBlock Definition(string id, string name, string title, Formula formula, string prose) =>
        Describe.Lean(DescribeId.Create("calderon-"+id),Handle(name),H(title),StatementSource.FromAuthor(Disp(formula)),
            AssessedProvenance.FromLiterature(Note),Blocks(Paragraph(Text(prose))),DescribeRole.Definition);
    private static DeclarationHandle Handle(string name) => DeclarationHandle.Create(
        "D5/S3/Arith/Congruence/QuadraticOrderMoments/CalderonReciprocalMoments."+name);
    private static Formula LiteralSet() => Seq(OpenBrace,Z,Sp,Colon,Sp,Ring,Sp,Mid,Sp,
        Exists("x",Nat,Exists("y",Nat,And(And(Leq(Num(1),V("x")),Leq(V("x"),Pow(P,K))),
            And(And(Leq(Num(1),V("y")),Leq(V("y"),Pow(P,K))),
                And(new Formula.Not(And(Dvd(P,V("x")),Dvd(P,V("y")))),Eqn(Z,Element(V("x"),V("y")))))))),CloseBrace);
    private static Formula MomentBounds(Formula? instance = null) => And(
        Mem(instance is null ? Call("H1",P,T,N,K) : Call("H1",P,instance,T,N,K),
            Span(Pow(Coerce(P,instance is null ? Ring : Call("R",P,instance,T,N)),Mul(Num(2),K)))),
        Mem(instance is null ? Call("H2",P,T,N,K) : Call("H2",P,instance,T,N,K),
            Span(Pow(Coerce(P,instance is null ? Ring : Call("R",P,instance,T,N)),K))));
    private static Formula ClaimFormula() => All("p",Nat,All("hp",Call("Fact",Call("Prime",P)),
        All("T",Int,All("N",Int,Imp(Call("Admissible",P,V("hp"),T,N),
            All("k",Nat,Imp(Leq(Num(1),K),MomentBounds(V("hp")))))))));
    private static Formula V(string name) => F.Id(name);
    private static Formula Call(string name, params Formula[] args) => new Formula.FunctionCall(FormulaIdentifier.Create(name),[..args]);
    private static Formula Parenthesized(Formula value) => Seq(Open,value,Close);
    private static Formula Coerce(Formula value, Formula type) => Parenthesized(Seq(value,Sp,Colon,Sp,type));
    private static Formula All(string name, Formula type, Formula body) => new Formula.Bind(FormulaQuantifier.ForAll,FormulaIdentifier.Create(name),type,body);
    private static Formula Exists(string name, Formula type, Formula body) => new Formula.Bind(FormulaQuantifier.Exists,FormulaIdentifier.Create(name),type,body);
    private static Formula Add(Formula a, Formula b) => new Formula.Binary(a,FormulaBinaryOperator.Add,b);
    private static Formula Sub(Formula a, Formula b) => new Formula.Binary(a,FormulaBinaryOperator.Subtract,b);
    private static Formula Mul(Formula a, Formula b) => new Formula.Binary(a,FormulaBinaryOperator.Multiply,b);
    private static Formula Pow(Formula a, Formula b) => new Formula.Power(a,b);
    private static Formula Eqn(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.Equal,b);
    private static Formula Dvd(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.Divides,b);
    private static Formula Less(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.LessThan,b);
    private static Formula Leq(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.LessThanOrEqual,b);
    private static Formula Mem(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.MemberOf,b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.And,Parenthesized(b));
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.Implies,Parenthesized(b));
    private static Formula Iffn(Formula a, Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.Iff,Parenthesized(b));
    private static Formula Span(Formula value) => Call("IdealSpan",new Formula.SetLiteral([value]));
    private static Formula Nat => new Formula.NamedConstant(FormulaIdentifier.Create("Nat"));
    private static Formula Int => new Formula.Integers();
    private static Formula P => V("p");
    private static Formula T => V("T");
    private static Formula N => V("N");
    private static Formula K => V("k");
    private static Formula Z => V("z");
    private static Formula Zp => Call("PadicInt",P);
    private static Formula Ring => Call("R",P,T,N);
    private static Formula Adm => Call("Admissible",P,T,N);
    private static Formula Polynomial => Add(Sub(Pow(V("X"),Num(2)),Mul(Call("C",Coerce(T,Zp)),V("X"))),Call("C",Coerce(N,Zp)));
    private static Formula Root => Call("AdjoinRootRoot",Polynomial);
    private static Formula Element(Formula x, Formula y) => Call("element",P,T,N,x,y);
    private static Formula Disc => Sub(Pow(T,Num(2)),Mul(Num(4),N));
    private static Formula Representatives => Call("U",P,T,N,K);
    private static Formula Params(Formula body) => All("p",Nat,Seq(OpenBracket,Call("Fact",Call("Prime",P)),CloseBracket,Comma,Sp,All("T",Int,All("N",Int,body))));
    private static Formula SumOver(Formula value) => Seq(new Formula.Subscript(Sum,Mem(Z,Representatives)),Sp,value);
    private static LibraryNoteRef Note => LibraryNoteRef.Create("D5/L/QuadraticForms/calderon2026rectangular");
}
